static void ui_event_led_switch(lv_event_t *e)
{
    int requested_state;

    if (lv_event_get_code(e) != LV_EVENT_VALUE_CHANGED)
        return;

    requested_state = lv_obj_has_state(lv_event_get_target(e), LV_STATE_CHECKED) ? 1 : 0;
    if (requested_state != led_is_enabled())
        on_led_toggle(e);
    ui_screen4_refresh();
}

